local InkMaker = {}
local PRODUCTS = {
    common_iron_gall_ink = { name = "Navadno železno črnilo", glassCost = 1, ironCost = 1, time = 3, cost = 30, happiness = 1, description = "Navadno železno-galunovo črnilo za pisarno." },
    lampblack_ink_vial = { name = "Viale črnega črnila", glassCost = 2, ironCost = 1, time = 5, cost = 80, happiness = 1, prestige = 1, description = "Črno črnilo iz saj v stekleni viale." },
    red_cinnabar_ink = { name = "Rdeče cinabaritno črnilo", glassCost = 2, ironCost = 1, silverCost = 1, time = 8, cost = 220, happiness = 2, prestige = 4, description = "Rdeče cinabaritno črnilo za plemiške listine." },
    silver_gilded_ink = { name = "Srebrno pozlačeno črnilo", glassCost = 3, silverCost = 2, goldCost = 1, time = 12, cost = 580, happiness = 3, prestige = 12, description = "Srebrno črnilo z zlatim prahom za visoke plemiče." },
    gold_powdered_ink = { name = "Zlatoprašno črnilo", glassCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, time = 16, cost = 1400, happiness = 5, prestige = 25, description = "Črnilo z zlatim prahom in dragulji za visoko plemstvo." },
    royal_imperial_ink = { name = "Kraljevsko imperialno črnilo", glassCost = 5, goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 23, cost = 3500, happiness = 11, prestige = 58, description = "Veliko kraljevsko imperialno črnilo z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    ink_workshop = { name = "Črilna delavnica", cost = { gold = 220, wood = 100, stone = 80, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    pigment_mill = { name = "Pigmentni mlin", cost = { gold = 800, wood = 240, stone = 220, iron = 6, glass = 8 }, upkeep = 18, qualityBonus = 18 },
    alchemical_atelier = { name = "Alkemični atelje", cost = { gold = 2200, wood = 360, stone = 480, silver = 28, glass = 14 }, upkeep = 50, qualityBonus = 30 },
    royal_ink_palace = { name = "Kraljevska črilna palača", cost = { gold = 9200, wood = 580, stone = 720, gold = 55, jewel = 14, glass = 30 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 50 },
}
InkMaker.glassStock = 14; InkMaker.ironStock = 12; InkMaker.silverStock = 8; InkMaker.goldStock = 6; InkMaker.jewelStock = 4; InkMaker.pearlStock = 4
InkMaker.productStock = {}; InkMaker.buildings = {}; InkMaker.maker = nil; InkMaker.activeMaking = {}; InkMaker.totalProducts = 0; InkMaker.dayTimer = 0
function InkMaker.init() InkMaker.glassStock=14; InkMaker.ironStock=12; InkMaker.silverStock=8; InkMaker.goldStock=6; InkMaker.jewelStock=4; InkMaker.pearlStock=4; InkMaker.productStock={}; InkMaker.buildings={}; InkMaker.maker=nil; InkMaker.activeMaking={}; InkMaker.totalProducts=0; InkMaker.dayTimer=0; print("[InkMaker] Royal Ink Maker System initialized (6 products, 4 buildings)") end
function InkMaker.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; InkMaker.maker={name=n or ("Črilar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Črilar najet: %s (spretnost: %d)",InkMaker.maker.name,s),"success") end; return true end
function InkMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function InkMaker.build(id) local ok,e=InkMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(InkMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function InkMaker.getQualityBonus() local b=0; for _,bd in ipairs(InkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function InkMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and InkMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.ironCost and InkMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and InkMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and InkMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and InkMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and InkMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #InkMaker.buildings==0 then return false,"Potrebna črilna delavnica" end; if not InkMaker.maker then return false,"Potreben črilar" end; return true end
function InkMaker.make(pt,qty) qty=qty or 1; local ok,e=InkMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then InkMaker.glassStock=InkMaker.glassStock-d.glassCost*qty end; if d.ironCost then InkMaker.ironStock=InkMaker.ironStock-d.ironCost*qty end; if d.silverCost then InkMaker.silverStock=InkMaker.silverStock-d.silverCost*qty end; if d.goldCost then InkMaker.goldStock=InkMaker.goldStock-d.goldCost*qty end; if d.jewelCost then InkMaker.jewelStock=InkMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then InkMaker.pearlStock=InkMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if InkMaker.maker then t=math.max(1,t-math.floor(InkMaker.maker.skill/13)) end; table.insert(InkMaker.activeMaking,{id="ink_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kuhanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function InkMaker.completeMaking(m) local q=1.0+(InkMaker.getQualityBonus()/100); if InkMaker.maker then q=q+(InkMaker.maker.skill/150) end; q=math.min(2.4,q); InkMaker.productStock[m.productType]=(InkMaker.productStock[m.productType] or 0)+m.quantity; InkMaker.totalProducts=InkMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if InkMaker.maker then InkMaker.maker.itemsMade=InkMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then InkMaker.maker.skill=math.min(100,InkMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Črnilo pripravljeno: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ink.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function InkMaker.update(dt) if not _G.state then return end; InkMaker.dayTimer=InkMaker.dayTimer+dt; if InkMaker.dayTimer>=30 then InkMaker.dayTimer=0; for i=#InkMaker.activeMaking,1,-1 do local m=InkMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then InkMaker.completeMaking(m); table.remove(InkMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(InkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if InkMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function InkMaker.getStats() return {glassStock=InkMaker.glassStock,ironStock=InkMaker.ironStock,silverStock=InkMaker.silverStock,goldStock=InkMaker.goldStock,jewelStock=InkMaker.jewelStock,pearlStock=InkMaker.pearlStock,productStock=InkMaker.productStock,numBuildings=#InkMaker.buildings,hasMaker=InkMaker.maker~=nil,makerName=InkMaker.maker and InkMaker.maker.name or "—",makerSkill=InkMaker.maker and InkMaker.maker.skill or 0,activeMaking=#InkMaker.activeMaking,totalProducts=InkMaker.totalProducts} end
return InkMaker
